// Version changes context and primary-reference edition; shared lessons remain shared.
let odooVersion='19';try{odooVersion=localStorage.getItem('odoo-course-version')==='20'?'20':'19'}catch{}
const versionSelect=()=>`<label class="version-select">Learning edition <select id="odooVersion" aria-label="Odoo version"><option value="19" ${odooVersion==='19'?'selected':''}>Odoo 19</option><option value="20" ${odooVersion==='20'?'selected':''}>Odoo 20</option></select></label>`;
const oldLayout=layout;layout=function(content,view){return oldLayout(`<div class="edition-bar">${versionSelect()}<span>Fictional business · General accounting · ${topics.length} open lessons</span><a href="#sandbox">Try the business lab ↗</a></div>`+content,view).replace('Let’s play','Story studio').replace('Animation studio','Story studio').replace('100 ideas. A curious brain. A pencil is optional.','100 business ideas. One connected company. Your own pace.')};
const oldCourse=course;course=()=>oldCourse().replace('across 7 chapters','across 14 chapters').replace('A whole world of possibilities.','The whole business connected.');
function editionNote(t){if(['inventory-cost','close-inventory','close-accrual','inventory-advanced'].includes(t.id))return `Odoo ${odooVersion}: Inventory tracks physical-movement value. Accounting uses the configured periodic-at-closing or perpetual-at-invoicing model with stock-closing/accrual review. This post-19 approach applies to both editions.`;if(t.chapter===12)return `Odoo ${odooVersion}: choose the matching payroll localization, employment terms, working schedule, and salary structure. Field names, rules, and availability depend on that installed localization; this example uses fictional general arithmetic.`;if(t.id==='product-master')return `Odoo ${odooVersion}: use Goods / Service / Combo as applicable and inspect Track Inventory for goods. Verify the actual product form rather than applying an older storable/consumable checklist.`;if(t.id==='account-register'||t.id==='account-bank')return `Odoo ${odooVersion}: payment entries and In Payment / Paid states depend on payment-method and outstanding-account configuration. Inspect the entry and required bank reconciliation.`;return `Odoo ${odooVersion}: this core business workflow is shared with ${odooVersion==='19'?'20':'19'}. Use the selected edition’s reference below for exact screens and options. Availability depends on installed apps, edition, localization, settings, and role.`}
const oldLesson=lesson;lesson=function(t){const panel=`<section class="functional-context"><div><span class="scribble">Before you touch a button…</span><h2>Your functional starting kit.</h2><p><strong>Who:</strong> ${esc(t.role)}</p><p><strong>Where to start:</strong> ${esc(t.nav)}</p><p><strong>Prepare:</strong> ${esc(t.setup)}</p></div><aside class="edition-note"><span class="tiny-pill">ODOO ${odooVersion} · VERSION CONTEXT</span><p>${esc(editionNote(t))}</p><a href="https://www.odoo.com/documentation/${odooVersion}.0/${t.refPath}" target="_blank" rel="noopener">Open official ${odooVersion} reference ↗</a></aside></section>`;const exercise=`<section class="lesson-section case-work"><span class="scribble red-note">You’re the consultant now.</span><h2>Try a real decision.</h2><p>${esc(t.practice)}</p><details id="solution"><summary>Reveal the worked reasoning →</summary><p>${esc(t.solution)}</p></details><p class="evidence-note"><strong>Acceptance evidence:</strong> ${esc(t.control)}</p></section>`;return oldLesson(t).replace('<section id="experiment"',panel+'<section id="experiment"').replace('<section class="lesson-section notes-paper">',exercise+'<section class="lesson-section notes-paper">')};
const odooCommon=bindCommon;bindCommon=function(){odooCommon();$('#odooVersion').onchange=e=>{odooVersion=e.target.value;try{localStorage.setItem('odoo-course-version',odooVersion)}catch{}const scroll=window.scrollY;route();window.scrollTo(0,scroll);toast('Now learning with Odoo '+odooVersion+' references.')};if($('#businessFlow'))bindBusinessFlow()};
const homeChapters=()=>chapterInfo.map((c,i)=>`<a class="book-chapter" href="#course/${i}"><span class="chapter-big">${String(i+1).padStart(2,'0')}</span><div><h3>${c[0]}</h3><p>${c[1]}</p><span class="chapter-preview">${topics.filter(t=>t.chapter===i).slice(0,3).map(t=>t.title).join(' · ')}…</span></div><span class="scribble">${topics.filter(t=>t.chapter===i).length} stories ↗</span></a>`).join('');
home=function(){const next=topics.find(t=>t.id===progress.last)||topics[0];return `<div class="book-kicker"><span>THE ODOO FUNCTIONAL NOTEBOOK · 19 & 20</span><span class="scribble">for the “wait… why?” kind of mind ↙</span></div><section class="notebook-hero"><div class="hero-copy"><span class="yellow-tape">Simple stories. Serious business understanding.</span><h1>${siteConfig.title}</h1><p>${siteConfig.description}</p><div class="row"><a class="btn primary" href="#lesson/${progress.visited.length?next.id:'foundations'}">${progress.visited.length?'Continue my story':'Open the first story'} →</a><a class="text-link" href="#course">Browse the whole book ↗</a></div><div class="hero-pencil-note">See it. Predict it. Try it.<span>Then explain it.</span>${pencilArrow()}</div><div class="home-stats"><span><strong>100</strong> little stories</span><span><strong>14</strong> deep chapters</span><span><strong>2</strong> Odoo editions</span></div></div><div class="hero-scrap business-scrap"><div class="torn-label">Exhibit A: one chair, many promises</div><div id="businessFlow" class="business-flow" aria-live="polite"></div><div class="pancake-controls"><button class="btn primary" id="flowNext">Follow the next promise →</button><button class="btn" id="flowReset">Reset ↺</button></div><p class="scribble" id="flowCaption" role="status"></p><span class="stamp-note">A TRAINING STORY · YOU CONTROL THE NEXT MOVE</span></div></section><div class="notebook-divider"><span>Your brain learns by doing</span></div><section class="learn-method"><article><span class="scribble method-number">01.</span><h3>A story you can picture.</h3><p>Meet Oak & Co, a little chair maker. Shelves, recipes, promises, and money jars make the big words approachable.</p></article><article><span class="scribble method-number">02.</span><h3>Watch the records change.</h3><p>Step through every lesson’s worked animation. Pause, rewind, predict, and inspect the actual business event.</p></article><article><span class="scribble method-number">03.</span><h3>Think like a consultant.</h3><p>Check configuration, arrange the steps, spot the trap, solve a case, and explain your answer in your own words.</p></article></section><section class="capstone-banner"><div><span class="scribble">Your own little business laboratory ↗</span><h2>What happens if only six chairs ship?</h2><p>Change quantities, policies, material supply, journal amounts, and payroll inputs. Make the consequences visible.</p></div><a class="btn primary" href="#sandbox">Open the five live labs →</a></section><div class="section-head book-contents-head"><div><span class="scribble red-note">Every team has a chapter ↓</span><h2>The whole company, in your notebook.</h2><p>From the first inquiry to the period close. No locked chapters. Learn at your own pace.</p></div><a class="text-link" href="#course">Open all 100 lessons →</a></div><section class="book-chapters">${homeChapters()}</section><div class="sticky-question"><span class="scribble">Brand new to Odoo?</span><p>Start with the chair story. Learn the everyday idea first, then its proper functional name and the evidence to check.</p><a href="#lesson/foundations" class="text-link">Open page one →</a></div><p class="source-note">Original lessons inspired by a visual notebook approach. Official references: <a href="https://www.odoo.com/documentation/19.0/" target="_blank" rel="noopener">Odoo 19</a> · <a href="https://www.odoo.com/documentation/20.0/" target="_blank" rel="noopener">Odoo 20</a>. Business arithmetic uses fictional inputs and general principles.</p>`};
function bindBusinessFlow(){let step=0;const names=['Ask','Promise','Make','Deliver','Invoice','Settle'],records=['CRM opportunity','Sales order: 10 chairs','Manufacturing: 10 chairs','Validated delivery: 10','Posted invoice: 1000','Payment + bank reviewed'],messages=['North Shop asks about ten chairs. Interest is not a completed sale.','The confirmed sales order records the promise. It does not prove shipment.','The workshop records real consumption and finished output. A recipe alone cannot make chairs.','The validated shipment records the physical delivery. Under delivered policy it establishes invoiceable quantity.','At 100 each, ten chairs create a simple 1000 invoice before tax. The invoice is not cash.','Check the payment, residual, and configured bank reconciliation. Every part of the story needs its own evidence.'];function draw(){$('#businessFlow').innerHTML=`<div class="flow-cards">${names.map((n,i)=>`<div class="flow-card ${i===step?'now':i<step?'passed':''}"><span>${i<step?'✓':String(i+1).padStart(2,'0')}</span><strong>${n}</strong><small>${records[i]}</small></div>`).join('')}</div><div class="chair-sketch" aria-hidden="true"><svg viewBox="0 0 110 80"><path d="M29 8l-5 42h53l-5-42zM24 50l-3 24m56-24l5 24M26 41h49M35 12l-1 26m13-26v26m13-26l1 26" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg><span class="scribble">same chair.<br>different facts.</span></div>`;$('#flowCaption').textContent=messages[step];$('#flowNext').textContent=step===5?'Tell the story again ↺':'Follow the next promise →'}$('#flowNext').onclick=()=>{step=(step+1)%6;draw()};$('#flowReset').onclick=()=>{step=0;draw()};draw()}
cheatsheet=function(){return `<div class="page-intro"><span class="yellow-tape">Your functional revision notebook</span><h1>Know the record.<br>Check the evidence.</h1><p>100 practical controls, grouped by module. Odoo ${odooVersion} reference edition.</p><button class="btn" id="printSheet">Print / save as PDF ↗</button></div><label for="sheetFilter" class="visually-hidden">Filter revision notes</label><input id="sheetFilter" class="filter-input" placeholder="Filter by module, topic, or evidence…"><div class="table-wrap"><table><thead><tr><th>Module / idea</th><th>What to verify</th><th>Common trap</th></tr></thead><tbody id="sheetRows">${topics.map(t=>`<tr><td>${esc(t.module)}<br><a href="#lesson/${t.id}">${esc(t.title)} ↗</a></td><td>${esc(t.control)}</td><td>${esc(t.trap)}</td></tr>`).join('')}</tbody></table></div>`};
const labSpecs={sales:{name:'Sales: what can be invoiced?',intro:'An ordered-policy invoice follows the ordered quantity. A delivered-policy invoice follows validated delivered quantity. Subtract what was already invoiced.',fields:[['ordered','Ordered chairs',10],['delivered','Delivered chairs',6],['invoiced','Previously invoiced',0],['price','Price per chair',100]],lesson:'invoice-policy'},inventory:{name:'Inventory: refill the cupboard',intro:'This simplified min/max rule compares forecast with minimum and fills to maximum, rounded to an order multiple. Real proposals also depend on dates, routes, and existing supply.',fields:[['onhand','On hand',8],['incoming','Planned incoming',4],['outgoing','Planned outgoing',9],['minimum','Minimum',5],['maximum','Maximum',12],['multiple','Order multiple',1]],lesson:'inventory-reorder'},manufacturing:{name:'Manufacturing: scale the recipe',intro:'First divide target output by BoM output. Then scale the component recipe. Available material determines whether this simple one-component job is ready.',fields:[['target','Target chairs',5],['bomoutput','BoM output chairs',2],['legs','Legs in this BoM',8],['available','Available legs',16]],lesson:'mrp-bom'},accounting:{name:'Accounting: balance does not prove meaning',intro:'Build a simple illustrative excluded-tax customer invoice: debit receivable, credit revenue, credit tax. Check balance, then inspect the economic meaning.',fields:[['debit','Debit receivable',110],['revenue','Credit revenue',100],['tax','Credit tax liability',10]],lesson:'account-double-entry'},payroll:{name:'Payroll: whose deduction is it?',intro:'Illustrative net pay equals gross earnings minus employee deductions. Employer contributions add to employer cost separately. Real localized salary rules use their defined bases and conditions.',fields:[['basic','Basic earnings',2000],['allowance','Allowances',200],['deduction','Employee deductions',150],['employer','Employer contributions',200]],lesson:'payroll-rules'}};
function sandbox(){return `<div class="page-intro"><span class="yellow-tape">THE OAK & CO BUSINESS LAB · ODOO ${odooVersion}</span><h1>Turn a little knob.<br>See the business change.</h1><p>Five small models to build intuition. Numbers stay in your browser; these exercises do not create records in an Odoo database.</p></div><label class="scribble" for="businessLab">Choose your experiment:</label><select class="lab-picker" id="businessLab">${Object.entries(labSpecs).map(([k,l])=>`<option value="${k}">${l.name}</option>`).join('')}</select><section class="live-lab"><div id="labIntroduction"></div><div class="lab-workspace"><form id="businessInputs"></form><div class="lab-output" id="businessResult" aria-live="polite"></div></div><div class="row"><button class="btn" id="resetBusiness">Reset this experiment ↺</button><a class="btn primary" id="businessLesson" href="#lesson/invoice-policy">Read the full story →</a></div></section><p class="source-note">Assumptions are stated in each model. Taxes, deductions, wages, and accounting figures are fictional. Dates, rounding, localized rules, multiple components, returns, and other exceptions require the actual configured workflow.</p>`}
function bindSandbox(){let key='sales';const money=n=>n.toLocaleString(undefined,{maximumFractionDigits:2}),tile=(label,value)=>`<div class="result-tile"><span>${label}</span><strong>${money(value)}</strong></div>`;function init(){const s=labSpecs[key];$('#labIntroduction').innerHTML=`<span class="scribble">What if…?</span><h2>${s.name}</h2><p>${s.intro}</p>`;$('#businessInputs').innerHTML=s.fields.map(([id,label,v])=>`<label>${label}<input type="number" id="${id}" name="${id}" min="0" max="100000000" step="any" value="${v}" required></label>`).join('')+(key==='sales'?'<label>Invoice policy<select id="policy"><option value="delivered">Delivered quantities</option><option value="ordered">Ordered quantities</option></select></label>':'');$('#businessInputs').onsubmit=e=>e.preventDefault();$('#businessInputs').oninput=draw;$('#businessLesson').href='#lesson/'+s.lesson;draw()}function draw(){const v={};for(const [id] of labSpecs[key].fields){const raw=$('#'+id).value;v[id]=Number(raw);if(raw===''||!Number.isFinite(v[id])||v[id]<0||v[id]>1e8){$('#businessResult').innerHTML='<p class="lab-error">Enter non-negative numbers up to 100,000,000 in every field.</p>';return}}let html='';if(key==='sales'){if(v.delivered>v.ordered){html='<p class="lab-error">This simple example assumes delivered does not exceed ordered. Reduce delivered or increase ordered.</p>'}else{const base=$('#policy').value==='ordered'?v.ordered:v.delivered,q=Math.max(0,base-v.invoiced);html=tile('Policy quantity',base)+tile('Invoiceable now',q)+tile('Net amount before tax',q*v.price)+`<p>${money(base)} policy units − ${money(v.invoiced)} already invoiced. ${v.invoiced>base?'Prior invoices exceed today’s policy basis: investigate credits, timing, or changed policy.':'Only the remaining positive quantity is offered for invoicing.'}</p>`}}else if(key==='inventory'){if(v.maximum<v.minimum||v.multiple<=0){html='<p class="lab-error">Maximum must be at least minimum, and order multiple must be greater than zero.</p>'}else{const f=v.onhand+v.incoming-v.outgoing,raw=f<v.minimum?Math.max(0,v.maximum-f):0,q=Math.ceil(raw/v.multiple)*v.multiple;html=tile('Forecast',f)+tile('Proposed supply',q)+tile('Forecast after supply',f+q)+`<p>${money(v.onhand)} + ${money(v.incoming)} − ${money(v.outgoing)} = ${money(f)}. ${q?'Forecast is below minimum; round the target shortage up to the configured multiple.':'Forecast is at or above minimum, so this simplified rule does not trigger.'}</p>`}}else if(key==='manufacturing'){if(v.bomoutput<=0){html='<p class="lab-error">BoM output must be greater than zero.</p>'}else{const factor=v.target/v.bomoutput,need=v.legs*factor,short=Math.max(0,need-v.available);html=tile('Recipe multiplier',factor)+tile('Required legs',need)+tile('Material shortage',short)+`<p>${money(v.legs)} × (${money(v.target)} ÷ ${money(v.bomoutput)}) = ${money(need)} legs. ${short?'Resolve the shortage before assuming production readiness.':'Material covers this simplified requirement; other components and operations still need review.'}</p>`}}else if(key==='accounting'){const credits=v.revenue+v.tax,diff=v.debit-credits;html=tile('Debit total',v.debit)+tile('Credit total',credits)+tile('Debit − credit',diff)+`<p class="${Math.abs(diff)<.005?'lab-success':'lab-error'}">${Math.abs(diff)<.005?'Balanced to displayed currency precision. Still verify accounts, partner, dates, and the real economic event.':'Unbalanced: equalize justified debit and credit amounts. Do not invent a balancing line without a real reason.'}</p>`}else{const gross=v.basic+v.allowance,net=gross-v.deduction;html=tile('Gross earnings',gross)+tile('Employee net',net)+tile('Employer total cost',gross+v.employer)+`<p>${money(gross)} − ${money(v.deduction)} = ${money(net)} employee net. Employer contribution ${money(v.employer)} is counted separately.${net<0?' Negative net requires investigation under localized policy.':''}</p>`}$('#businessResult').innerHTML=html}$('#businessLab').onchange=e=>{key=e.target.value;init()};$('#resetBusiness').onclick=init;init()}
const odooRoute=route;route=function(){if(location.hash.split('/')[0]==='#sandbox'){stopBook();clearInterval(timer);timer=null;currentTopic=null;$('#app').innerHTML=layout(sandbox(),'playground');bindCommon();bindSandbox();window.scrollTo(0,0)}else odooRoute();document.title=(currentTopic?currentTopic.title:location.hash==='#sandbox'?'Business lab':'The connected business')+' — Odoo '+odooVersion+' fieldnotes';document.body.dataset.subject='ODOO'};window.removeEventListener('hashchange',odooRoute);window.addEventListener('hashchange',route);route();
